CREATE OR REPLACE PROCEDURE public.sp_update_emergency_contact(IN p_id uuid, IN p_tenant_id uuid, IN p_organization_id uuid, IN p_branch_id uuid, IN p_scope character varying, IN p_category character varying, IN p_name character varying, IN p_phone_number character varying, IN p_alternate_phone_number character varying, IN p_country_region character varying, IN p_address text, IN p_instructions text, IN p_verification_status character varying, IN p_verified_by character varying, IN p_verified_at timestamp with time zone, IN p_review_due_at timestamp with time zone, IN p_is_active boolean, IN p_display_order integer)  LANGUAGE plpgsql AS $procedure$ BEGIN     UPDATE emergency_contacts SET         organization_id = p_organization_id,         branch_id = p_branch_id,         scope = p_scope,         category = p_category,         name = p_name,         phone_number = p_phone_number,         alternate_phone_number = p_alternate_phone_number,         country_region = p_country_region,         address = p_address,         instructions = p_instructions,         verification_status = p_verification_status,         verified_by = p_verified_by,         verified_at = p_verified_at,         review_due_at = p_review_due_at,         is_active = p_is_active,         display_order = p_display_order,         updated_at = CURRENT_TIMESTAMP     WHERE tenant_id = p_tenant_id AND id = p_id; END; $procedure$ ;
